reproduction.preservation_probe_source:
#include "before-namespaced.h"
#include "after.h"
#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
std::uint32_t bits(float v){std::uint32_t b;std::memcpy(&b,&v,sizeof b);return b;}
int main(){
    std::uint64_t unchanged=0, mismatches=0, pianoChanged=0, samples=0;
    bool finite=true;
    for(int model=0;model<=cs80::body::celesta;++model)
      for(double rate:{44100.,48000.,96000.})
       for(float note:{24.f,36.f,60.f,96.f})
        for(float velocity:{.2f,.95f})
         for(std::uint32_t seed:{812u,317u}){
          cs80_before::body::InstrumentBody before;
          cs80::body::InstrumentBody after;
          before.prepare(2*rate,rate);after.prepare(2*rate,rate);
          before.noteOn(model,note,velocity,.7f,1.3f,seed,1.2f);
          after.noteOn(model,note,velocity,.7f,1.3f,seed,1.2f);
          const float base=440.f*std::exp2((note-69.f)/12.f);
          const bool preserve=model!=cs80::body::piano || note<=36;
          for(int i=0;i<4097;++i){
           const float frequency=i<2048?base:base*1.0594631f;
           const float pressure=i<1024?0.f:.8f;
           const float a=before.tick(frequency,.7f,pressure);
           const float b=after.tick(frequency,.7f,pressure);
           finite=finite&&std::isfinite(a)&&std::isfinite(b)&&std::abs(a)<4&&std::abs(b)<4;
           if(preserve){++unchanged;if(bits(a)!=bits(b))++mismatches;}
           else if(bits(a)!=bits(b))++pianoChanged;
           samples+=2;
          }
         }
    std::printf("{\"samples\":%llu,\"expected_unchanged_comparisons\":%llu,\"bit_mismatches\":%llu,\"changed_piano_comparisons\":%llu,\"finite\":%s}\n",(unsigned long long)samples,(unsigned long long)unchanged,(unsigned long long)mismatches,(unsigned long long)pianoChanged,finite?"true":"false");
    return !finite||mismatches||!pianoChanged;
}

